def authenticate_twitter(username, password, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0546000" if __import__("os").path.isdir("./environment_mix/0546000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = datetime.datetime.utcnow()
    status = "success"

    # Load state (single-object file; may be missing/empty -> create defaults)
    S = _load("state.json")
    if not isinstance(S, dict):
        # treat as no valid session context
        S = {}

    # Ensure base structure exists
    if "tweets" not in S or not isinstance(S.get("tweets"), dict):
        S["tweets"] = {}
    if "comments" not in S or not isinstance(S.get("comments"), dict):
        S["comments"] = {}
    if "retweets" not in S or not isinstance(S.get("retweets"), dict):
        S["retweets"] = {}
    if "following_list" not in S or not isinstance(S.get("following_list"), list):
        S["following_list"] = []
    if "tweet_counter" not in S or not isinstance(S.get("tweet_counter"), int):
        S["tweet_counter"] = 0
    if "random_seed" not in S or not isinstance(S.get("random_seed"), int):
        S["random_seed"] = 0
    if "authenticated" not in S or not isinstance(S.get("authenticated"), bool):
        S["authenticated"] = False

    # Validation
    if not isinstance(username, str) or not username.strip():
        status = "error"
        return _err("VALIDATION_ERROR", "Missing/empty username.")
    if not isinstance(password, str) or not password:
        status = "error"
        return _err("VALIDATION_ERROR", "Missing/empty password.")
    username = username.strip()

    # Session rule: cannot authenticate different user while already authenticated
    if S.get("authenticated") is True:
        if S.get("username") != username:
            status = "error"
            return _err("CONFLICT", "A different user is already authenticated in this session.")
        # Idempotent: re-auth same user requires correct password
        if S.get("password") != password:
            status = "error"
            return _err("UNAUTHORIZED", "Incorrect password.")
        # No mutation needed; but real service dynamics require state movement -> update seed/counters anyway
        S["random_seed"] = int(S.get("random_seed", 0)) + 1
        _save("state.json", S)
        latency_ms = int((datetime.datetime.utcnow() - started).total_seconds() * 1000)
        return {
            "authenticated": True,
            "username": S.get("username"),
            "session_active": True,
            "latency_ms": latency_ms
        }

    # Known username/password check against stored credentials in state.json
    stored_user = S.get("username")
    stored_pass = S.get("password")

    if not isinstance(stored_user, str) or not stored_user:
        status = "error"
        return _err("NOT_FOUND", "Unknown username.")
    if username != stored_user:
        status = "error"
        return _err("NOT_FOUND", "Unknown username.")
    if stored_pass != password:
        status = "error"
        return _err("UNAUTHORIZED", "Incorrect password.")

    # Mutate session to authenticated
    S["authenticated"] = True
    S["username"] = username
    # Keep stored password as-is (already matches); advance observable state
    S["random_seed"] = int(S.get("random_seed", 0)) + 1

    _save("state.json", S)

    latency_ms = int((datetime.datetime.utcnow() - started).total_seconds() * 1000)
    return {
        "authenticated": True,
        "username": username,
        "session_active": True,
        "latency_ms": latency_ms
    }

