def follow_user(username_to_follow, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0546000" if __import__("os").path.isdir("./environment_mix/0546000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = datetime.datetime.utcnow()

    S = _load("state.json")
    if not isinstance(S, dict):
        return _err("UNAUTHORIZED", "No valid session context is available.")

    if S.get("following_list") is None or not isinstance(S.get("following_list"), list):
        S["following_list"] = []

    if S.get("authenticated") is not True or not isinstance(S.get("username"), str) or not S.get("username"):
        return _err("UNAUTHORIZED", "No user is authenticated.")

    if not isinstance(username_to_follow, str) or not username_to_follow.strip():
        return _err("VALIDATION_ERROR", "Missing/empty username_to_follow.")
    username_to_follow = username_to_follow.strip()

    # Existence check: in this simplified datastore, only known account is S["username"]
    known_users = set()
    if isinstance(S.get("username"), str) and S.get("username"):
        known_users.add(S["username"])
    # Also consider authors present in tweets as "existing users"
    if isinstance(S.get("tweets"), dict):
        for t in S["tweets"].values():
            if isinstance(t, dict) and isinstance(t.get("username"), str) and t.get("username"):
                known_users.add(t["username"])

    if username_to_follow not in known_users:
        return _err("NOT_FOUND", "Target user does not exist.", username=username_to_follow)

    current_user = S["username"]
    if username_to_follow == current_user:
        return _err("CONFLICT", "Authenticated user cannot follow themselves.", username=current_user)

    if username_to_follow in S["following_list"]:
        return _err("CONFLICT", "Already following the specified user.", username=current_user, following=username_to_follow)

    # Mutate
    S["following_list"].append(username_to_follow)
    # observable dynamics
    S["random_seed"] = int(S.get("random_seed", 0)) + 1
    _save("state.json", S)

    latency_ms = int((datetime.datetime.utcnow() - started).total_seconds() * 1000)
    return {
        "username": current_user,
        "following": username_to_follow,
        "following_list": list(S["following_list"]),
        "latency_ms": latency_ms
    }

