def post_tweet(content, tags=None, mentions=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0546000" if __import__("os").path.isdir("./environment_mix/0546000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = datetime.datetime.utcnow()

    S = _load("state.json")
    if not isinstance(S, dict):
        return _err("UNAUTHORIZED", "No valid session context is available.")

    if S.get("authenticated") is not True or not isinstance(S.get("username"), str) or not S.get("username"):
        return _err("UNAUTHORIZED", "No user is authenticated.")

    if not isinstance(content, str):
        return _err("VALIDATION_ERROR", "content must be a string.")
    if not content.strip():
        return _err("VALIDATION_ERROR", "content cannot be empty or whitespace.")

    if tags is None:
        tags = []
    if mentions is None:
        mentions = []

    if not isinstance(tags, list) or any(not isinstance(x, str) for x in tags):
        return _err("VALIDATION_ERROR", "tags must be an array of strings.")
    if not isinstance(mentions, list) or any(not isinstance(x, str) for x in mentions):
        return _err("VALIDATION_ERROR", "mentions must be an array of strings.")

    bad_tags = [t for t in tags if not t.startswith("#")]
    if bad_tags:
        return _err("VALIDATION_ERROR", "All tags must start with '#'.", invalid_tags=bad_tags)

    bad_mentions = [m for m in mentions if not m.startswith("@")]
    if bad_mentions:
        return _err("VALIDATION_ERROR", "All mentions must start with '@'.", invalid_mentions=bad_mentions)

    if "tweets" not in S or not isinstance(S.get("tweets"), dict):
        S["tweets"] = {}
    if "tweet_counter" not in S or not isinstance(S.get("tweet_counter"), int):
        S["tweet_counter"] = 0

    # Allocate id
    next_id = int(S["tweet_counter"])
    # Ensure uniqueness if store was edited
    while str(next_id) in S["tweets"] or next_id in S["tweets"]:
        next_id += 1

    tweet = {
        "id": next_id,
        "username": S["username"],
        "content": content,
        "tags": list(tags),
        "mentions": list(mentions)
    }

    # Persist with string key (JSON object keys are strings)
    S["tweets"][str(next_id)] = tweet
    S["tweet_counter"] = next_id + 1
    # observable dynamics
    S["random_seed"] = int(S.get("random_seed", 0)) + 1

    _save("state.json", S)

    latency_ms = int((datetime.datetime.utcnow() - started).total_seconds() * 1000)
    out = dict(tweet)
    out["latency_ms"] = latency_ms
    return out

