def search_tweets(keyword, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0546000" if __import__("os").path.isdir("./environment_mix/0546000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = datetime.datetime.utcnow()

    if not isinstance(keyword, str):
        return _err("VALIDATION_ERROR", "keyword must be a string.")
    kw = keyword.strip()
    if not kw:
        return _err("VALIDATION_ERROR", "keyword cannot be empty.")
    # simple "too broad" guard
    if len(kw) < 2:
        return _err("VALIDATION_ERROR", "keyword is too broad to execute under service limits.")

    S = _load("state.json")
    if not isinstance(S, dict):
        return _err("UNAUTHORIZED", "Session state cannot be read or is invalidated.")

    tweets_obj = S.get("tweets")
    if not isinstance(tweets_obj, dict):
        tweets_obj = {}

    kw_low = kw.lower()
    matches = []
    for _, t in tweets_obj.items():
        if not isinstance(t, dict):
            continue
        content = t.get("content", "")
        tags = t.get("tags", [])
        if not isinstance(content, str):
            content = str(content)
        if not isinstance(tags, list):
            tags = []
        in_content = kw_low in content.lower()
        in_tags = any(kw_low in str(tag).lower() for tag in tags)
        if in_content or in_tags:
            matches.append(t)

    # observable dynamics
    if not isinstance(S.get("random_seed"), int):
        S["random_seed"] = 0
    S["random_seed"] = int(S["random_seed"]) + 1
    _save("state.json", S)

    latency_ms = int((datetime.datetime.utcnow() - started).total_seconds() * 1000)
    return {
        "keyword": kw,
        "total": len(matches),
        "tweets": matches,
        "latency_ms": latency_ms
    }

def unfollow_user(username_to_unfollow, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0546000" if __import__("os").path.isdir("./environment_mix/0546000") else "/app/database")
