        return _err("VALIDATION_ERROR", "Missing/empty username_to_unfollow.")
    username_to_unfollow = username_to_unfollow.strip()

    # Existence check: known users derived similarly as follow_user
    known_users = set()
    if isinstance(S.get("username"), str) and S.get("username"):
        known_users.add(S["username"])
    if isinstance(S.get("tweets"), dict):
        for t in S["tweets"].values():
            if isinstance(t, dict) and isinstance(t.get("username"), str) and t.get("username"):
                known_users.add(t["username"])

    if username_to_unfollow not in known_users:
